CREATE TABLE IF NOT EXISTS users(name TEXT PRIMARY KEY, role TEXT, salt TEXT, hash TEXT);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user TEXT REFERENCES users,expires INTEGER,csrf TEXT);
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY,name TEXT,kind TEXT,unit TEXT,scale INTEGER);
CREATE TABLE IF NOT EXISTS products(item INTEGER PRIMARY KEY REFERENCES items,yield INTEGER,carton INTEGER,price INTEGER,hsn TEXT,gst_bp INTEGER);
CREATE TABLE IF NOT EXISTS bom(product INTEGER REFERENCES products,item INTEGER REFERENCES items,qty INTEGER,PRIMARY KEY(product,item));
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY,name TEXT,state TEXT,gstin TEXT,address TEXT);
CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY,name TEXT);
CREATE TABLE IF NOT EXISTS movements(id INTEGER PRIMARY KEY,day TEXT,item INTEGER REFERENCES items,qty INTEGER,value INTEGER,source TEXT);
CREATE INDEX IF NOT EXISTS movement_item ON movements(item,day);
CREATE TABLE IF NOT EXISTS purchases(id INTEGER PRIMARY KEY,day TEXT,supplier INTEGER REFERENCES suppliers,item INTEGER REFERENCES items,qty INTEGER,value INTEGER);
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY,day TEXT,product INTEGER REFERENCES products,batches INTEGER,expected INTEGER,good INTEGER,damaged INTEGER,labour INTEGER DEFAULT 0,energy INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS issues(run INTEGER REFERENCES runs,item INTEGER REFERENCES items,planned INTEGER,actual INTEGER,cost INTEGER,PRIMARY KEY(run,item));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,day TEXT,customer INTEGER REFERENCES customers,seller TEXT REFERENCES users,status TEXT);
CREATE TABLE IF NOT EXISTS lines(ord INTEGER REFERENCES orders, product INTEGER REFERENCES products,qty INTEGER,price INTEGER,PRIMARY KEY(ord,product));
CREATE TABLE IF NOT EXISTS invoices(id INTEGER PRIMARY KEY,ord INTEGER UNIQUE REFERENCES orders,day TEXT,fy TEXT,seq INTEGER,taxable INTEGER,cgst INTEGER,sgst INTEGER,igst INTEGER,UNIQUE(fy,seq));
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,day TEXT,invoice INTEGER REFERENCES invoices,amount INTEGER);
CREATE TABLE IF NOT EXISTS credits(id INTEGER PRIMARY KEY,day TEXT,invoice INTEGER UNIQUE REFERENCES invoices,reason TEXT);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,stamp TEXT DEFAULT CURRENT_TIMESTAMP,actor TEXT,action TEXT,detail TEXT);
CREATE TABLE IF NOT EXISTS requests(user TEXT,key TEXT,PRIMARY KEY(user,key));
